  fill:{ code:'nums = [3, -1, 0, 7, -5]\nprint(list(___1___(lambda x: x > 0, nums)))', blanks:[{ a:['filter'], opt:['map','filter','select','sorted'] }], why:'filter(함수, 목록)은 함수가 True인 값만 골라요.' },
